import{e as r,ab as a,a1 as o,m as i,r as n,p as s}from"./chunks/framework.BGh0NSIy.js";const m=JSON.parse('{"title":"Monthly Updates [August]","description":"August 2025 updates","frontmatter":{"title":"Monthly Updates [August]","description":"August 2025 updates","date":"2025-08-01T00:00:00.000Z","next":false,"prev":false,"footer":true},"headers":[],"relativePath":"posts/aug-2025.md","filePath":"posts/aug-2025.md"}'),l={name:"posts/aug-2025.md"};function d(p,e,h,f,g,c){const t=a("Post");return o(),i("div",null,[n(t,{authors:"nbats"}),e[0]||(e[0]=s('<div class="info custom-block"><p class="custom-block-title">INFO</p><p>These update threads only contain major updates. If you&#39;re interested in seeing all minor changes you can follow our <a href="https://github.com/fmhy/FMHYedit/commits/main" target="_blank" rel="noreferrer">Commits Page</a> on GitHub or <a href="https://redd.it/17f8msf" target="_blank" rel="noreferrer">Updates Channel</a> in Discord.</p></div><h1 id="wiki-updates" tabindex="-1">Wiki Updates <a class="header-anchor" href="#wiki-updates" aria-label="Permalink to &quot;Wiki Updates&quot;">​</a></h1><ul><li><p>Did a complete <strong><a href="https://fmhy.pages.dev/other/contributing" target="_blank" rel="noreferrer">Contribution Guide</a></strong> rewrite. It&#39;s now more intuitive and fully up-to-date. TY to Hugo.</p></li><li><p>Added <a href="https://fmhy.net/linux-macos#server-selfhosting" target="_blank" rel="noreferrer">Server / Selfhosting</a> section to Linux.</p></li><li><p>Added <a href="https://fmhy.net/educational#exams-tests" target="_blank" rel="noreferrer">Exams / Tests</a> section to Educational Tools. This also helped debloat the study section a bit.</p></li><li><p>Added <a href="https://fmhy.net/video#classics-public-domain" target="_blank" rel="noreferrer">Classic / Public Domain</a> + <a href="https://fmhy.net/video#film-archives" target="_blank" rel="noreferrer">Film Archive</a> sections to Specialty Streaming.</p></li><li><p>Added <a href="https://fmhy.pages.dev/misc#hacker-news-tools" target="_blank" rel="noreferrer">Hacker News Tools</a> section to News Sites.</p></li><li><p>Added <a href="https://fmhy.net/educational#sign-language" target="_blank" rel="noreferrer">Sign Language</a> section to Language Learning.</p></li><li><p>Added <a href="https://fmhy.net/misc#assistance-charity" target="_blank" rel="noreferrer">Assistance / Charity</a> section to Free Stuff.</p></li><li><p>Added <a href="https://fmhy.net/misc#vehicle" target="_blank" rel="noreferrer">Vehicle</a> section to Miscellaneous.</p></li><li><p>Moved <a href="https://fmhy.net/educational#coding-tutorials" target="_blank" rel="noreferrer">Coding Tutorials</a> out of storage, reformatted, added labels and removed some sites. <a href="https://i.ibb.co/0VVhmrrT/image.png" target="_blank" rel="noreferrer">Before vs. After</a></p></li><li><p>Moved <a href="https://fmhy.net/mobile#telegram-clients" target="_blank" rel="noreferrer">Android Telegram Clients</a> out of storage, cleaned it up, added labels. <a href="https://i.ibb.co/276xNQWS/image.png" target="_blank" rel="noreferrer">Before vs. After</a></p></li><li><p>Moved <a href="https://fmhy.net/image-tools#media-covers-posters" target="_blank" rel="noreferrer">Media Covers / Posters</a> out of storage + added labels. <a href="https://i.ibb.co/DDrN5zDt/image.png" target="_blank" rel="noreferrer">Before vs. After</a></p></li><li><p>Moved <a href="https://fmhy.net/audio#album-artwork" target="_blank" rel="noreferrer">Album Artwork</a> out of storage + added labels.</p></li><li><p>Moved <a href="https://fmhy.net/developer-tools#static-page-hosting" target="_blank" rel="noreferrer">Static Page Hosting</a> out of storage + reorganized and added labels. <a href="https://i.ibb.co/Kpq1shtP/Untitled.png" target="_blank" rel="noreferrer">Before vs. After</a></p></li><li><p>Cleaned up <a href="https://fmhy.net/internet-tools#link-in-bio" target="_blank" rel="noreferrer">Link in Bio</a> section, removed sites that didn&#39;t stand out + starred Carrd. <a href="https://i.ibb.co/8gfjXg2G/image.png" target="_blank" rel="noreferrer">Before vs. After</a></p></li><li><p>Cleaned up <a href="https://fmhy.net/reading#ebooks" target="_blank" rel="noreferrer">Ebook section</a>, added / fixed labels, moved sites that didn&#39;t fit the section. <a href="https://i.ibb.co/0yYcZQWW/Untitled.jpg" target="_blank" rel="noreferrer">Before vs. After</a></p></li><li><p>Cleaned up <a href="https://fmhy.net/audio#spotify-tools" target="_blank" rel="noreferrer">Spotify Tools</a> + <a href="https://fmhy.net/audio#playlist-tools" target="_blank" rel="noreferrer">Spotify Playlist Tools</a>. Re-organized + removed sites that didn&#39;t stand out.</p></li><li><p>Cleaned up formatting in <a href="https://fmhy.net/privacy#adblocking" target="_blank" rel="noreferrer">Adblock section</a>. <a href="https://i.ibb.co/0jcysGV3/Adblock-Before.png" target="_blank" rel="noreferrer">Before vs. After</a></p></li><li><p>Decided to bring back our <a href="https://saidit.net/s/freemediaheckyeah/wiki/index" target="_blank" rel="noreferrer">Saidit backup</a>. Saidit has always supported us; their owner actually posted FMHY themselves on the main Saidit wiki. It&#39;s always good to have places like this that we know we can trust.</p></li><li><p>To make streaming easier to navigate, we&#39;ve separated <a href="https://fmhy.net/video#api-frontends" target="_blank" rel="noreferrer">API Frontends</a> and <a href="https://fmhy.net/video#single-server" target="_blank" rel="noreferrer">Single Server</a> sites into their own sections.</p></li><li><p>Thank you to Hugo, Samidy, Dan, kick, Anarchydr, and everyone else who helped re-organize or create the sections this month.</p></li></ul><hr><h1 id="stars-added-⭐" tabindex="-1">Stars Added ⭐ <a class="header-anchor" href="#stars-added-⭐" aria-label="Permalink to &quot;Stars Added ⭐&quot;">​</a></h1><ul><li><p>Starred <a href="https://fmhy.net/audio#song-identification" target="_blank" rel="noreferrer">Google Assistant</a> in Song Identification. Works by humming songs; seems to be even more accurate than Shazam in our testing.</p></li><li><p>Starred <a href="https://fmhy.net/ai#image-generation" target="_blank" rel="noreferrer">Qwen</a> in Image Gen. Unlimited, no signup required; seems to be almost as good as 4o as of now.</p></li><li><p>Starred <a href="https://fmhy.net/social-media-tools#reddit-tools" target="_blank" rel="noreferrer">Redlib</a> in Reddit Tools. Privacy-friendly Reddit frontend, works without an account.</p></li><li><p>Starred <a href="https://fmhy.net/text-tools#typing-lessons" target="_blank" rel="noreferrer">keybr</a> in Typing Lessons. Custom touch typing practice, has nice UI, multiplayer, profiles, themes, etc.</p></li><li><p>Starred <a href="https://fmhy.net/mobile#android-youtube-apps" target="_blank" rel="noreferrer">Seal</a> in Android YouTube Downloaders. Open-source downloader that supports many sites.</p></li><li><p>Starred <a href="https://fmhy.net/mobile#battery-tools" target="_blank" rel="noreferrer">SaverTuner</a> in Android Battery Tools. Battery saving app that many people have had good results with in our testing.</p></li><li><p>Starred <a href="https://fmhy.net/mobile#social-media-apps" target="_blank" rel="noreferrer">Xtra</a> in Android Social Media. Open-source Twitch client that seems to work well for people.</p></li><li><p>Starred <a href="https://fmhy.net/video#live-sports" target="_blank" rel="noreferrer">FSTV</a> in Live Sports. Has fast streams + covers a solid amount of leagues.</p></li><li><p>Starred <a href="https://fmhy.net/audio#audio-metadata" target="_blank" rel="noreferrer">MusicBrainz Picard</a> in Audio Metadata. Big catalog, good for batch metadata automation and sorting.</p></li><li><p>Starred <a href="https://fmhy.net/misc#drinks" target="_blank" rel="noreferrer">Beanconqueror</a> in Drinks section. Open-source, ad-free, and <a href="https://i.ibb.co/1GkdXk4N/image.png" target="_blank" rel="noreferrer">feature-rich</a> brew tracking app.</p></li><li><p>Starred <a href="https://fmhy.net/gaming#crosswords" target="_blank" rel="noreferrer">Crosshare</a> in Crossword section. Feature-rich, custom UI, active userbase and new puzzles daily.</p></li><li><p>Starred <a href="https://fmhy.net/educational#computer-science" target="_blank" rel="noreferrer">CS50</a> in Computer Science. Well-respected Harvard Computer Science Course.</p></li></ul><hr><h1 id="things-removed" tabindex="-1">Things Removed <a class="header-anchor" href="#things-removed" aria-label="Permalink to &quot;Things Removed&quot;">​</a></h1><ul><li><p>Removed nsw2u, nswdl, ps4pkg, and game-2u as they&#39;ve been targeted and <a href="https://torrentfreak.com/fbi-seizes-gaming-piracy-domains-including-pre-release-target-nsw2u/" target="_blank" rel="noreferrer">shut down</a> by the FBI.</p></li><li><p>Removed InstallGentoo Wiki as it&#39;s been taken over by trolls. As of now the site should be avoided (NSFL content), but we&#39;ll consider re-adding if the situation ever gets handled.</p></li><li><p>Removed HuggingChat as it&#39;s <a href="https://x.com/julien_c/status/1940082259287069089" target="_blank" rel="noreferrer">shut down</a>. Note that HuggingFace still works; it&#39;s only chat that&#39;s gone.</p></li><li><p>Removed Cobalt from YT downloaders as it <a href="https://x.com/justusecobalt/status/1943279590178230618" target="_blank" rel="noreferrer">no longer supports YouTube</a>. Note that it still supports other video sites, so we&#39;ve kept it in other sections it fits in.</p></li><li><p>Removed Masquerade Repacks as they&#39;ve <a href="https://i.ibb.co/0pndbGNP/image.png" target="_blank" rel="noreferrer">called it quits</a>; note that Kaos itself is still going strong.</p></li></ul>',9))])}const b=r(l,[["render",d]]);export{m as __pageData,b as default};
